import React from 'react'
import ReactApexChart from 'react-apexcharts'
import './styles.css'

const ApexChart = () => {
  const [state, setState] = React.useState({
    series: [
      { name: 'Budget below', data: [-13, -23, -20, -8] },
      { name: 'Budget above', data: [44, 55, 41, 37] },
      { name: 'Actual below', data: [-21, -7, -25, -13] },
      { name: 'Actual above', data: [11, 17, 15, 15] },
    ],
    options: {
      chart: {
        type: 'bar',
        height: 380,
        stacked: true,
      },
      plotOptions: {
        bar: {
          horizontal: true,
          borderRadius: 10,
          borderRadiusApplication: 'end',
        },
      },
      colors: ['#008FFB', '#4FC3F7', '#00E396', '#66DA26'],
      dataLabels: {
        enabled: false,
      },
      stroke: {
        width: 1,
        colors: ['#fff'],
      },
      title: {
        text: 'ungrouped bar, mixed: single stack, outermost segments cap',
        style: { fontSize: '13px', fontWeight: 500 },
      },
      xaxis: {
        categories: ['Q1', 'Q2', 'Q3', 'Q4'],
      },
      legend: {
        position: 'top',
      },
    },
  })

  return (
    <div>
      <div id="chart">
        <ReactApexChart
          options={state.options}
          series={state.series}
          type="bar"
          height={380}
        />
      </div>
    </div>
  )
}

export default ApexChart
